<?php
declare(strict_types=1);require_once __DIR__.'/_auth.php';require_once __DIR__.'/../vendor/autoload.php';
use EnglAI\Analytics\AnalyticsService;use EnglAI\Mvp\ClassroomService;use EnglAI\Security\Csrf;
require_admin();$cid=(int)($_GET['classroom_id']??0);$mid=(int)($_GET['member_id']??0);$actor=(string)($_SESSION['admin_username']??'admin');$classroom=(new ClassroomService(db()))->requireOwned($cid,$actor);$data=(new AnalyticsService(db()))->student($cid,$mid);
$q=db()->prepare("SELECT a.id,a.score,a.assessment_status,a.assessment_source,a.transcript,a.writing_submission,a.rubric_json,s.question,s.skill,q.title quiz_title FROM quiz_answers a JOIN quiz_session_questions s ON s.id=a.session_question_id JOIN quiz_sessions q ON q.id=a.quiz_session_id JOIN quiz_participants p ON p.id=a.participant_id WHERE q.classroom_id=? AND p.member_id=? AND s.skill IN('speaking','writing') ORDER BY a.id DESC");$q->execute([$cid,$mid]);$assessments=$q->fetchAll();
?>
