<section class="card dashboard-hero"><span class="eyebrow">Student Identity #<?=$mid?></span><h1><?=htmlspecialchars($data['member']['display_name']?:'Student')?> <span class="gradient-text">Progress</span></h1><p class="muted"><?=htmlspecialchars($classroom['name'])?> · joined <?=htmlspecialchars($data['member']['created_at'])?> · latest <?=htmlspecialchars($data['member']['last_seen_at']?:'—')?></p><div class="row"><span class="badge available">Strongest: <?=htmlspecialchars(ucfirst($data['strongest_skill']?:'insufficient data'))?></span><span class="badge dev">Improve: <?=htmlspecialchars(ucfirst($data['weakest_skill']?:'insufficient data'))?></span><a class="button secondary" href="/admin/export.php?classroom_id=<?=$cid?>&member_id=<?=$mid?>&type=student_csv">Export CSV</a></div></section>
<section class="grid four"><?php foreach($data['skills'] as $skill=>$v):?><article class="card"><h3><?=ucfirst($skill)?></h3><div class="stat"><?=$v['average_score']?>%</div><p class="muted"><?=$v['attempts']?> completed attempts</p></article><?php endforeach;?></section>
<?php if(!$data['skills']):?><div class="card empty">Belum cukup aktivitas untuk membuat analisis.</div><?php endif;?>
<section class="grid two"><article class="card"><h2>Recent Self Learning</h2><table><thead><tr><th>Activity</th><th>Skill</th><th>Level</th><th>Score</th></tr></thead><tbody><?php foreach($data['recent'] as $r):?><tr><td><?=htmlspecialchars($r['title'])?></td><td><?=ucfirst($r['skill'])?></td><td><?=ucfirst($r['level'])?></td><td><?=$r['score']?>%</td></tr><?php endforeach;?></tbody></table></article><article class="card"><h2>Historical Leaderboard</h2><table><thead><tr><th>Quiz</th><th>Rank</th><th>Score</th><th>Achievement</th></tr></thead><tbody><?php foreach($data['quiz_history'] as $r):?><tr><td><?=htmlspecialchars($r['title']?:'Quiz #'.$r['id'])?></td><td>#<?=htmlspecialchars((string)($r['final_rank']?:'—'))?></td><td><?=(int)$r['total_score']?></td><td><?=htmlspecialchars($r['achievement']?:'—')?></td></tr><?php endforeach;?></tbody></table></article></section>
<section class="card"><h2>Speaking & Writing Review</h2><p class="muted">AI Speaking Feedback berbasis transcription; bukan pronunciation assessment.</p><table><thead><tr><th>Quiz</th><th>Skill</th><th>Score</th><th>Source</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($assessments as $a):?><tr><td><?=htmlspecialchars($a['quiz_title'])?></td><td><?=ucfirst($a['skill'])?></td><td><?=(int)$a['score']?>/1000</td><td><?=htmlspecialchars((string)$a['assessment_source'])?></td><td><?=htmlspecialchars($a['assessment_status'])?></td><td><a class="button secondary" href="/admin/assessment_review.php?classroom_id=<?=$cid?>&answer_id=<?=(int)$a['id']?>">Review</a></td></tr><?php endforeach;?></tbody></table></section>
